package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchApiTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void searching_by_part_of_title_returns_matching_books() throws Exception {
        String token = UUID.randomUUID().toString();
        String bookId = registerBook("Spring in Action " + token);

        mockMvc.perform(get("/books").param("title", token))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(bookId))
                .andExpect(jsonPath("$[0].title").value("Spring in Action " + token))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void search_ignores_case() throws Exception {
        String token = UUID.randomUUID().toString();
        String bookId = registerBook("CLEAN CODE " + token);

        mockMvc.perform(get("/books").param("title", "clean code " + token.toLowerCase()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(bookId));
    }

    @Test
    void search_with_no_match_returns_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", "no-such-book-" + UUID.randomUUID()))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void search_treats_wildcard_characters_literally() throws Exception {
        String token = UUID.randomUUID().toString();
        registerBook("Rust 100% " + token);

        mockMvc.perform(get("/books").param("title", "100%_" + token))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void search_without_title_returns_400() throws Exception {
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private String registerBook(String title) throws Exception {
        String response = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(response).get("id").asText();
    }
}
